import asyncio, json, base64
from playwright.async_api import async_playwright
URL='file:///home/claude/shots/app.html'
# صورة PNG صغيرة 2×2 للاختبار
PNG = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR4nGNk+M/AwMDAxMDAwMDAAAANHQEDasKb6QAAAABJRU5ErkJggg==')
R=[]
def ok(n,c,x=''): R.append(c); print('PASS' if c else 'FAIL', n, x, flush=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); ctx = await b.new_context(viewport={'width':1440,'height':900}, accept_downloads=True); pg = await ctx.new_page(); errs=[]
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(URL); await pg.wait_for_selector('#main .page'); await pg.wait_for_timeout(700)
        E=pg.evaluate
        async def go(h): await E(f"location.hash==={json.dumps(h)} ? route() : (location.hash={json.dumps(h)})"); await pg.wait_for_timeout(900)
        ok('nav has «مركز الصور» and «مسار الشراكة»', await E("!!document.querySelector('.nav-a[href=\"#/media\"]') && !!document.querySelector('.nav-a[href=\"#/process\"]')"))
        # ===== مركز الصور =====
        await go('#/media')
        n = await E("mediaItems().length")
        ok('photo center collects photos from partnerships, achievements and home', n > 0 and await E("new Set(mediaItems().flatMap(i=>i.uses.map(u=>u.src))).size") >= 3, n)
        ok('grid shows every photo', await E("document.querySelectorAll('.m-tile').length") == n)
        ok('stats: total, real, illustrative, coverage', await E("document.querySelectorAll('.m-stats>div').length") == 4 and await E("+document.querySelector('.m-stats b').textContent") == n)
        ok('real signing photos are included', await E("mediaItems().some(i=>i.fileId==='asset:border-guard-signing')"))
        await pg.check('#mReal'); await pg.wait_for_timeout(300)
        ok('«real photos only» hides illustrative images', await E("document.querySelectorAll('.m-tile').length") == await E("mediaItems().filter(i=>!i.illus).length") and await E("!document.querySelector('.m-tile .illus')"))
        await pg.uncheck('#mReal'); await pg.wait_for_timeout(300)
        pid = await E("mediaItems().find(i=>i.pid).pid")
        await pg.select_option('#mPid', pid); await pg.wait_for_timeout(300)
        ok('filter by partnership', await E("document.querySelectorAll('.m-tile').length") == await E(f"mediaItems().filter(i=>i.pid==={json.dumps(pid)}).length"))
        await pg.select_option('#mPid', ''); await pg.wait_for_timeout(200)
        await pg.fill('#mQ', 'حرس'); await pg.wait_for_timeout(500)
        ok('search by partner name', await E("document.querySelectorAll('.m-tile').length") >= 1 and await E("[...document.querySelectorAll('.m-tile')].every(t=>t.textContent.includes('حرس'))"))
        await pg.fill('#mQ', ''); await pg.wait_for_timeout(400)
        await pg.click('[data-mview="albums"]'); await pg.wait_for_timeout(300)
        ok('albums view groups photos by partnership', await E("document.querySelectorAll('.m-album').length") >= 2)
        await pg.click('[data-mview="grid"]'); await pg.wait_for_timeout(300)
        await pg.click('.m-tile'); await pg.wait_for_timeout(500)
        ok('photo detail shows where it is used', await E("!!document.querySelector('.m-det') && document.querySelectorAll('.m-usel li').length>=1"))
        await pg.click('.m-det-img'); await pg.wait_for_timeout(500)
        ok('opens full-screen gallery', await E("!!document.querySelector('.lightbox.gal')"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(200); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        gaps = await E("document.querySelectorAll('.m-gap').length")
        ok('lists signed partnerships without real photos', gaps >= 1, gaps)
        # الرفع
        target = await E("visiblePartnerships().find(p=>!p.isDraft&&p.stage==='signed'&&!mediaItems().some(i=>i.pid===p.id&&!i.illus)).id")
        await pg.click(f'[data-mupload="{target}"]'); await pg.wait_for_timeout(400)
        ok('upload dialog preselects the partnership', await E("document.querySelector('#muP').value") == target)
        await pg.fill('#muT', 'زيارة ميدانية للاختبار')
        await pg.set_input_files('#muDrop input', files=[{'name':'a.png','mimeType':'image/png','buffer':PNG},{'name':'b.png','mimeType':'image/png','buffer':PNG}])
        await pg.wait_for_timeout(300)
        ok('upload previews the chosen images', await E("document.querySelectorAll('#muPrev img').length") == 2)
        await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(900)
        ok('uploaded images saved as partnership photos', await E(f"D.partnerships.find(p=>p.id==={json.dumps(target)}).attachments.filter(a=>a.category==='صور الشراكة'&&a.name.startsWith('زيارة ميدانية للاختبار')).length") == 2)
        ok('they appear in the photo center as real photos', await E(f"mediaItems().filter(i=>i.pid==={json.dumps(target)}&&!i.illus).length") == 2)
        ok('gap list shrinks after documenting', await E("document.querySelectorAll('.m-gap').length") == gaps - 1)
        ok('upload is logged in the audit trail', await E("D.audit.some(a=>/مركز الصور/.test(a.details||''))"))
        # جعلها غلافًا ثم حذفها
        await pg.fill('#mQ', 'زيارة ميدانية للاختبار'); await pg.wait_for_timeout(500)
        await pg.click('.m-tile'); await pg.wait_for_timeout(400)
        fid = await E("mediaItems().find(i=>/زيارة ميدانية للاختبار/.test(i.title)).fileId")
        await pg.click('[data-mcover]'); await pg.wait_for_timeout(600)
        ok('set as partnership cover', await E(f"D.partnerships.find(p=>p.id==={json.dumps(target)}).coverFileId") == fid)
        await pg.click('.m-tile'); await pg.wait_for_timeout(400)
        await pg.click('[data-mdel]'); await pg.wait_for_timeout(300); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(700)
        ok('delete removes the attachment (and the cover that used it)', await E(f"D.partnerships.find(p=>p.id==={json.dumps(target)}).attachments.filter(a=>a.name.startsWith('زيارة ميدانية للاختبار')).length") == 1 and await E(f"!D.partnerships.find(p=>p.id==={json.dumps(target)}).coverFileId || D.partnerships.find(p=>p.id==={json.dumps(target)}).coverFileId!=={json.dumps(fid)}"))
        await pg.fill('#mQ', ''); await pg.wait_for_timeout(300)
        # دور ممثل الإدارة: الصور العامة فقط ودون رفع
        await E("D.settings.session={role:'dept',dept:'الإدارة العامة للمشاريع'}; renderShell()"); await go('#/media')
        ok('department role: no upload button', not await E("!!document.querySelector('[data-mupload]')"))
        ok('department role: only public partnership photos', await E("mediaItems().filter(i=>i.uses.some(u=>u.src==='att')).every(i=>i.uses.filter(u=>u.src==='att').every(u=>u.t==='صور الشراكة'))") and await E("mediaItems().filter(i=>i.pid).every(i=>publicPartnerships().some(p=>p.id===i.pid)||D.achievements.some(a=>a.partnershipId===i.pid))"))
        # ===== مسار الشراكة (مولّد من المسار المطبق) =====
        await go('#/process')
        ok('process page reachable for department users too', await E("!!document.querySelector('.pr-map')"))
        await E("D.settings.session={role:'admin'}; renderShell()"); await go('#/process')
        ok('lanes for every party in the process', await E("[...document.querySelectorAll('.pr-lane-h b')].map(x=>x.textContent).join('|')") == 'الإدارة الطالبة|إدارة الشراكات|الإدارات المعنية|الإدارة الاستراتيجية|الإدارة القانونية|مكتب المعالي|إدارة تطوير الأعمال')
        ok('five phases from request to activation', await E("[...document.querySelectorAll('.pr-phase')].map(x=>x.textContent.replace(/\\d+/,'').trim()).join('|')") == 'الطلب والتقييم|الاجتماع وبناء المذكرة|مراجعة المذكرة|الاعتماد والتوقيع|التفعيل')
        ok('every step drawn as a node', await E("document.querySelectorAll('.pr-node').length") == await E("PR_STEPS.length"))
        ok('13 numbered workflow steps', await E("document.querySelectorAll('.pr-node .pr-num').length") == 13)
        ok('two entry points and two end points', await E("document.querySelectorAll('.pr-node.start').length") == 2 and await E("document.querySelectorAll('.pr-node.end').length") == 2)
        ok('decision/approval nodes (evaluation, strategy, legal, excellency)', await E("document.querySelectorAll('.pr-node.decision').length") == 4)
        ok('arrows drawn for every transition', await E("document.querySelectorAll('.pr-edges path.pr-e').length") == await E("PR_EDGES.length"))
        ok('returns loop back (strategy → draft, excellency → legal)', await E("PR_EDGES.some(e=>e[0]==='strategy'&&e[1]==='draft'&&e[3]==='back') && PR_EDGES.some(e=>e[0]==='excellency'&&e[1]==='legal'&&e[3]==='back')"))
        ok('live counts per step from the workflow state', await E("+(document.querySelector('[data-step=\"legal\"] .pr-n')||{textContent:0}).textContent") == await E("prAt('legal').length"))
        await pg.click('.pr-node[data-step="legal"]'); await pg.wait_for_timeout(500)
        ok('step panel: description, documents, accounts, records', await E("!!document.querySelector('#prDrawer .pr-dr-d') && document.querySelectorAll('#prDrawer .kv > div').length===2 && document.querySelectorAll('#prDrawer .dz2-dr-it').length") == await E("prAt('legal').length"))
        await pg.click('#prDrawer [data-gostep="excellency"]'); await pg.wait_for_timeout(700)
        ok('navigate to the next step from the panel', 'رفع المعاملة' in await E("document.querySelector('#prDrawer h3').textContent"))
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(400)
        rows = await E("document.querySelectorAll('.pr-mx tbody tr:not(.pr-mx-ph)').length")
        ok('responsibility matrix: one row per step', rows == 13, rows)
        ok('matrix derived from the applied workflow (read-only)', await E("document.querySelectorAll('.pr-mx button.rc').length") == 0 and await E("prRaci().legal.legal") == 'A' and await E("prRaci().partner.partnerships") == 'R')
        ok('required documents listed per step', 'المذكرة الموقعة بين الطرفين' in await E("document.querySelector('.pr-mx').textContent"))
        ok('accounts and their steps', await E("document.querySelectorAll('.pr-acct').length") >= 6)
        async with pg.expect_download() as dl: await pg.click('[data-prxls]')
        d = await dl.value
        ok('matrix exports to Excel', d.suggested_filename.endswith('.xlsx'), d.suggested_filename)
        # الطباعة الأفقية لهذه الصفحة فقط
        await E("window.dispatchEvent(new Event('beforeprint'))")
        ok('print: landscape page for the process map', 'landscape' in await E("(document.querySelector('#landPage')||{}).textContent||''"))
        await E("window.dispatchEvent(new Event('afterprint'))")
        await go('#/partnerships'); await E("window.dispatchEvent(new Event('beforeprint'))")
        ok('register prints landscape (wide table)', 'landscape' in await E("(document.querySelector('#landPage')||{}).textContent||''"))
        await E("window.dispatchEvent(new Event('afterprint'))")
        await go('#/stories'); await E("window.dispatchEvent(new Event('beforeprint'))")
        ok('other pages keep their own page size', 'landscape' not in await E("(document.querySelector('#landPage')||{}).textContent||''"))
        await E("window.dispatchEvent(new Event('afterprint'))")
        # الاتجاهات الستة
        for dz in ['classic','board']:
            await E(f"applyDesign('{dz}')"); await pg.wait_for_timeout(900)
            await go('#/media'); a = await E("document.querySelectorAll('.m-tile').length>0")
            await go('#/process'); c = await E("document.querySelectorAll('.pr-edges path.pr-e').length") == await E("PR_EDGES.length")
            ok(f'both pages work in the {dz} direction', a and c, [a, c, await E("document.querySelectorAll('.pr-edges path').length"), await E('App.route.name')])
        await E("applyDesign('classic')"); await pg.wait_for_timeout(600)
        await pg.set_viewport_size({'width':390,'height':844}); await go('#/process')
        ok('mobile: map scrolls inside its frame, page does not', await E("document.documentElement.scrollWidth <= innerWidth + 1"))
        await go('#/media')
        ok('mobile: photo center has no horizontal page scroll', await E("document.documentElement.scrollWidth <= innerWidth + 1"))
        ok('no page errors', not errs, errs[:3])
        await b.close()
    print(f'\n{sum(R)}/{len(R)} passed')
asyncio.run(main())
